  useEffect(()=>{const key=(event:KeyboardEvent)=>{if((event.ctrlKey||event.metaKey)&&event.key==='k'){event.preventDefault();searchRef.current?.focus()}};const hash=()=>setPage(route());window.addEventListener('keydown',key);window.addEventListener('hashchange',hash);return()=>{window.removeEventListener('keydown',key);window.removeEventListener('hashchange',hash)}},[]);
  const project=state?.projects.find(p=>p.id===projectId)||state?.projects[0];
  const chapter=project?.chapters.find(c=>c.id===chapterId)||project?.chapters[0];
  const selectProject=(id:string)=>{setProjectId(id);localStorage.setItem('mujian-project',id);setChapterId('');setPicker(false);setEpisodes(rows=>{rows.forEach(r=>{if(r.url)URL.revokeObjectURL(r.url)});return []})};
