  useEffect(()=>{if(!EMBEDDED||MODELS_ONLY)return;const parentOrigin=HOST_QUERY.get('parent_origin');const receive=(event:MessageEvent)=>{if(event.source!==window.parent||event.origin!==parentOrigin||event.data?.type!=='heli:navigate')return;const value=event.data.page;if(!pages.some(p=>p.id===value)||value==='settings')return;if(typeof event.data.project_id==='string'&&event.data.project_id){selectProject(event.data.project_id)}navigate(value)};window.addEventListener('message',receive);return()=>window.removeEventListener('message',receive)},[navigate]);
  if(!state)return <div className="boot"><img src="/brand.png" width={56} height={56} alt="幺爆导演台Logo"/><h2>幺爆导演台</h2><p>正在打开你的创作空间…</p><LoaderCircle className="spin" size={18}/>{notice&&<p className="error-text">{notice.text}</p>}</div>;
